import os, re, csv, json, numpy as np
try:
    from scipy.optimize import linear_sum_assignment
except Exception:
    linear_sum_assignment = None

N = 26
TOL_TAG = 'tol1e8'
OUT_ROOT = 'storage/noesis/nmap/inquire_v2'

# Canonicalization for boundary labels
CANON = {
  'xl':'xL','x_l':'xL','xleft':'xL','left':'xL','xmin':'xL','x_min':'xL',
  'xr':'xR','x_r':'xR','xright':'xR','right':'xR','xmax':'xR','x_max':'xR',
  'yb':'yB','y_b':'yB','ybottom':'yB','bottom':'yB','ymin':'yB','y_min':'yB',
  'yt':'yT','y_t':'yT','ytop':'yT','top':'yT','ymax':'yT','y_max':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}
INT_RE = re.compile(r'[-+]?\d+')
NUM_RE = re.compile(r'[-+]?\d+(?:\.\d+)?', re.I)
SIDE_RE = re.compile(r'(xL|xR|yB|yT|xl|xr|yb|yt|left|right|top|bottom|xmin|xmax|ymin|ymax|x_min|x_max|y_min|y_max)', re.I)

def read_lines(path):
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        return f.read().strip().splitlines()

def parse_pairs_raw(path):
    rows=[]
    if not os.path.exists(path): return rows
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            try:
                i = int(float(toks[0])); j = int(float(toks[1]))
                rows.append((i, j))
            except Exception:
                continue
    return rows

def parse_boundary_raw(path):
    rows=[]
    if not os.path.exists(path): return rows
    for ln in read_lines(path):
        itoks = INT_RE.findall(ln)
        if not itoks: 
            continue
        try:
            i = int(itoks[0])
        except Exception:
            continue
        m = SIDE_RE.search(ln)
        if not m: 
            continue
        s_raw = m.group(1)
        k = s_raw.replace(' ', '').replace(':','').replace(',','').replace('.','').lower()
        s = CANON.get(k, CANON.get(k.lower(), k))
        if s in ('xL','xR','yB','yT'):
            rows.append((i, s))
    return rows

def normalize_indices(rows, kind):
    # Normalize to 0-based indices, deduplicate pairs with ordering (i<j)
    if kind == 'pairs':
        idxs = [i for (i, _) in rows] + [j for (_, j) in rows]
    else:
        idxs = [i for (i, _) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}
    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N for v in idxs)
    meta = {'applied': False, 'mode': 'as-is'}
    out = set()
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind == 'pairs':
            for (i, j) in rows:
                a, b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a != b:
                    u, v = (a, b) if a < b else (b, a)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                a = i-1
                if 0 <= a < N:
                    out.add((a, s))
    else:
        if kind == 'pairs':
            for (i, j) in rows:
                if 0 <= i < N and 0 <= j < N and i != j:
                    u, v = (i, j) if i < j else (j, i)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                if 0 <= i < N:
                    out.add((i, s))
    return out, meta

def read_centers(path):
    rows=[]
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            rows.append([float(toks[0]), float(toks[1])])
    C = np.array(rows, float)
    if C.shape != (N, 2):
        raise ValueError(f"centers shape mismatch: {path} -> {C.shape}")
    return C

def load_pack(dir_root, centers_path=None):
    pr = os.path.join(dir_root, f'active_pairs_{TOL_TAG}.csv')
    bd = os.path.join(dir_root, f'active_boundary_{TOL_TAG}.csv')
    pairs_raw = parse_pairs_raw(pr)
    bound_raw = parse_boundary_raw(bd)
    pairs, m_pairs = normalize_indices(pairs_raw, 'pairs')
    bound, m_bound = normalize_indices(bound_raw, 'bound')
    C = read_centers(centers_path) if (centers_path and os.path.exists(centers_path)) else None
    return {'pairs': pairs, 'bound': bound, 'centers': C, 'meta': {'pairs_norm': m_pairs, 'bound_norm': m_bound}}

def jaccard(A, B):
    I = A & B; U = A | B
    J = float(len(I))/float(len(U)) if len(U) > 0 else 1.0
    return {'j': J, 'I': len(I), 'U': len(U)}

def align_map(CA, CB):
    M = np.sum((CA[:, None, :] - CB[None, :, :])**2, axis=2)
    if linear_sum_assignment is None:
        a_idx = np.lexsort((CA[:,1], CA[:,0]))
        b_idx = np.lexsort((CB[:,1], CB[:,0]))
        P = np.zeros(N, dtype=int); P[a_idx] = b_idx
        return P
    r, c = linear_sum_assignment(M)
    P = np.zeros(N, dtype=int); P[r] = c
    return P

def map_pairs(P, S):
    T = set()
    for (i, j) in S:
        a, b = int(P[i]), int(P[j])
        if a == b: 
            continue
        u, v = (a, b) if a < b else (b, a)
        T.add((u, v))
    return T

def map_bound(P, S):
    return set((int(P[i]), s) for (i, s) in S)

def write_json_csv(base, tag, res):
    os.makedirs(base, exist_ok=True)
    with open(os.path.join(base, f'{tag}.json'), 'w') as f:
        json.dump(res, f, indent=2, sort_keys=True)
    with open(os.path.join(base, f'{tag}.csv'), 'w', newline='') as f:
        w = csv.writer(f); w.writerow(['n','boundary_j','I_b','U_b','pairs_j','I_p','U_p'])
        w.writerow([N, res['boundary']['j'], res['boundary']['I'], res['boundary']['U'],
                       res['pairs']['j'],    res['pairs']['I'],    res['pairs']['U']])

def compare_two(A, B, out_base, tag):
    res = {
      'n': N,
      'boundary': jaccard(A['bound'], B['bound']),
      'pairs':    jaccard(A['pairs'], B['pairs']),
      'note': 'unaligned'
    }
    write_json_csv(out_base, f'{tag}_{TOL_TAG}', res)
    if A['centers'] is not None and B['centers'] is not None:
        P = align_map(A['centers'], B['centers'])
        Ab, Ap = map_bound(P, A['bound']), map_pairs(P, A['pairs'])
        res2 = {
          'n': N,
          'alignment': 'hungarian',
          'boundary': jaccard(Ab, B['bound']),
          'pairs':    jaccard(Ap, B['pairs'])
        }
        write_json_csv(out_base, f'{tag}_{TOL_TAG}_aligned', res2)

def consensus_sets(packs):
    # packs: dict name->pack (with 'bound','pairs')
    Bs = [packs[k]['bound'] for k in packs]
    Ps = [packs[k]['pairs'] for k in packs]
    inter_b = set.intersection(*Bs) if all(len(s)>=0 for s in Bs) else set()
    union_b = set.union(*Bs) if all(len(s)>=0 for s in Bs) else set()
    inter_p = set.intersection(*Ps) if all(len(s)>=0 for s in Ps) else set()
    union_p = set.union(*Ps) if all(len(s)>=0 for s in Ps) else set()
    sizes_b = {k: len(packs[k]['bound']) for k in packs}
    sizes_p = {k: len(packs[k]['pairs']) for k in packs}
    return {'boundary': {'intersection': len(inter_b), 'union': len(union_b), 'sizes': sizes_b},
            'pairs':    {'intersection': len(inter_p), 'union': len(union_p), 'sizes': sizes_p}}

def discover_inquire_packs(root):
    packs=[]
    if not os.path.exists(root):
        return packs
    # Root SOTA + subdirs (nudged)
    candidates=[root] + [os.path.join(root, d) for d in os.listdir(root) if os.path.isdir(os.path.join(root,d))]
    for p in candidates:
        c=os.path.join(p,'centers.txt'); r=os.path.join(p,'radii.txt')
        b=os.path.join(p,f'active_boundary_{TOL_TAG}.csv')
        pr=os.path.join(p,f'active_pairs_{TOL_TAG}.csv')
        if os.path.exists(c) and os.path.exists(r) and os.path.exists(b) and os.path.exists(pr):
            name=os.path.relpath(p, root).replace(os.sep,'_') or 'inquire_207_root'
            packs.append((name,p))
    return packs

def construct_packing():
    os.makedirs(OUT_ROOT, exist_ok=True)

    # Load SOTA packs
    noe = load_pack('storage/noesis/exports/sota_243', centers_path='storage/noesis/latest_centers.txt')
    sci = load_pack('storage/Scientia/nmap/n26', centers_path='storage/Scientia/nmap/n26/centers.txt')
    pro = load_pack('storage/Prometheus/nmap/n26', centers_path='storage/Prometheus/nmap/n26/centers.txt')
    inq = load_pack('storage/Inquire/nmap/n26', centers_path='storage/Inquire/nmap/n26/centers.txt')

    # 4-lineage consensus (SOTAs only)
    sotapacks = {'Noesis_243': noe, 'Scientia_259': sci, 'Prometheus_298': pro, 'Inquire_207': inq}
    cons4 = consensus_sets(sotapacks)
    with open(os.path.join(OUT_ROOT, f'consensus_4lineage_sotas_{TOL_TAG}.json'), 'w') as f:
        json.dump({'n':N, 'ids': list(sotapacks.keys()), **cons4}, f, indent=2, sort_keys=True)

    # Pairwise SOTA Jaccards (optional small matrix)
    pairs = [('Noesis_243','Scientia_259'),('Noesis_243','Prometheus_298'),('Noesis_243','Inquire_207'),
             ('Scientia_259','Prometheus_298'),('Scientia_259','Inquire_207'),('Prometheus_298','Inquire_207')]
    with open(os.path.join(OUT_ROOT, f'jaccard_matrix_sotas_{TOL_TAG}.csv'),'w',newline='') as f:
        w=csv.writer(f); w.writerow(['A','B','boundary_j','I_b','U_b','pairs_j','I_p','U_p'])
        for a,b in pairs:
            A=sotapacks[a]; B=sotapacks[b]
            jb=jaccard(A['bound'],B['bound']); jp=jaccard(A['pairs'],B['pairs'])
            w.writerow([a,b,jb['j'],jb['I'],jb['U'],jp['j'],jp['I'],jp['U']])

    # Discover Inquire packs (SOTA + nudged) and compute per-pack Jaccards vs the SOTA set
    inq_root='storage/Inquire/nmap/n26'
    found = discover_inquire_packs(inq_root)
    summary_rows=[]
    if not found:
        with open(os.path.join(OUT_ROOT,'inquire_v2_meta.json'),'w') as f:
            json.dump({'note':'No Inquire packs found','root':inq_root}, f, indent=2, sort_keys=True)
    for name, p in found:
        out_dir=os.path.join(OUT_ROOT, name); os.makedirs(out_dir, exist_ok=True)
        pack=load_pack(p, centers_path=os.path.join(p,'centers.txt'))
        for tag, ref in [('noesis243',noe),('scientia259',sci),('prometheus298',pro),('inquire207',inq)]:
            compare_two(pack, ref, out_dir, f'{name}_vs_{tag}')
        # For summary, record boundary J vs each reference (aligned if available else unaligned)
        def load_j(path_json, fallback_json):
            if os.path.exists(path_json):
                with open(path_json,'r') as f: return float(json.load(f)['boundary']['j'])
            with open(fallback_json,'r') as f: return float(json.load(f)['boundary']['j'])
        j_noe = load_j(os.path.join(out_dir,f'{name}_vs_noesis243_{TOL_TAG}_aligned.json'),
                       os.path.join(out_dir,f'{name}_vs_noesis243_{TOL_TAG}.json'))
        j_sci = load_j(os.path.join(out_dir,f'{name}_vs_scientia259_{TOL_TAG}_aligned.json'),
                       os.path.join(out_dir,f'{name}_vs_scientia259_{TOL_TAG}.json'))
        j_pro = load_j(os.path.join(out_dir,f'{name}_vs_prometheus298_{TOL_TAG}_aligned.json'),
                       os.path.join(out_dir,f'{name}_vs_prometheus298_{TOL_TAG}.json'))
        j_inq = load_j(os.path.join(out_dir,f'{name}_vs_inquire207_{TOL_TAG}_aligned.json'),
                       os.path.join(out_dir,f'{name}_vs_inquire207_{TOL_TAG}.json'))
        summary_rows.append([name, j_noe, j_sci, j_pro, j_inq])

    if found:
        with open(os.path.join(OUT_ROOT,'inquire_v2_summary.csv'),'w',newline='') as f:
            w=csv.writer(f); w.writerow(['pack','Jb_noesis243','Jb_scientia259','Jb_prometheus298','Jb_inquire207'])
            for r in summary_rows: w.writerow(r)

    # Return current Noesis packing unchanged
    c = np.loadtxt('storage/noesis/latest_centers.txt'); r = np.loadtxt('storage/noesis/latest_radii.txt')
    return np.array(c,float).reshape(N,2), np.array(r,float).reshape(N,)
